  "Nur ein bisschen, bitte.": "Solo un poco, por favor.",
  "Reicht das?": "¿Es suficiente?",
  "Ja, das ist genau richtig.": "Sí, así está perfecto.",
  "Wie viele Flaschen brauchen wir?": "¿Cuántas botellas necesitamos?",
  "Ich glaub, vier reichen.": "Creo que con cuatro basta.",
  "Wir haben noch zwei zu Hause.": "En casa todavía tenemos dos.",
  "Dann nehmen wir nur zwei mit.": "Pues nos llevamos solo dos.",
  "Wollen wir uns ein Stück Kuchen teilen?": "¿Compartimos un trozo de tarta?",
