  "Machst du bitte das Fenster zu?": "¿Cierras la ventana, por favor?",
  "Der Schlüssel hängt neben der Tür.": "La llave está colgada al lado de la puerta.",
  "Heute Abend koche ich, du spülst.": "Esta noche cocino yo y tú friegas.",
