  "Ich hab leider schon einen Termin.": "Por desgracia ya tengo una cita.",
  "Ich hab nächste Woche einen wichtigen Termin.": "La semana que viene tengo una cita importante.",
  "Nächste Woche hab ich mehr Zeit.": "La semana que viene tengo más tiempo.",
  "Was machst du nächste Woche?": "¿Qué haces la semana que viene?",
  "Das klingt nach einem schönen Wochenende.": "Eso suena a un buen fin de semana.",
  "Das klingt nach viel Arbeit.": "Eso suena a mucho trabajo.",
  "Wollen wir zusammen ins Kino gehen?": "¿Vamos juntos al cine?",
  "Sollen wir zusammen hingehen?": "¿Vamos juntos?",
  "Wir frühstücken am Sonntag zusammen.": "El domingo desayunamos juntos.",
