  "Fick mich.": "Fóllame.",
  "Wir haben miteinander geschlafen.": "Nos hemos acostado.",
  "Ich drück dir die Daumen.": "Te cruzo los dedos.",
  "Das ist mir Wurst.": "Me da exactamente igual.",
  "Das ist nicht das Gelbe vom Ei.": "Eso no es ninguna maravilla.",
  "Ich hab die Nase voll.": "Estoy hasta las narices.",
  "Du gehst mir auf die Nerven.": "Me estás poniendo de los nervios.",
  "Ich bin fix und fertig.": "Estoy hecho polvo.",
  "Das ist nicht mein Bier.": "Eso no es asunto mío.",
  "Jetzt haben wir den Salat.": "Ahora sí que la hemos liado.",
  "Da hast du Schwein gehabt.": "Ahí has tenido suerte.",
  "Red nicht um den heißen Brei herum.": "No te andes por las ramas.",
  "Da bist du auf dem Holzweg.": "Ahí vas muy equivocado.",
  "Lass die Kirche im Dorf.": "No exageres.",
  "Hast du Tomaten auf den Augen?": "¿Es que no ves nada?",
  "Zwei Fliegen mit einer Klappe schlagen.": "Matar dos pájaros de un tiro.",
  "Ich schwebe auf Wolke sieben.": "Estoy en una nube.",
  "Hals- und Beinbruch!": "¡Mucha mierda!",
  "Ich hab richtig Bock drauf.": "Tengo muchísimas ganas.",
  "Lügen haben kurze Beine.": "Antes se pilla a un mentiroso que a un cojo.",
  "Ende gut, alles gut.": "Bien está lo que bien acaba.",
  "Das Leben ist kein Ponyhof.": "La vida no es un camino de rosas.",
  "Das mag durchaus zutreffen, nur würde ich das nicht verallgemeinern.": "Puede que sea cierto, solo que yo no lo generalizaría.",
  "Im Prinzip geb ich dir recht, unter der Voraussetzung dass die Rahmenbedingungen stimmen.": "En principio te doy la razón, siempre que las condiciones marco sean las adecuadas.",
  "Da würde ich vorsichtig widersprechen wollen, so einfach ist die Sache nämlich nicht.": "Ahí discreparía con cautela, porque el asunto no es tan sencillo.",
  "Ehrlich gesagt halte ich diese Darstellung für etwas überspitzt.": "Sinceramente, esa descripción me parece algo exagerada.",
  "Es kommt letztlich darauf an welche Kriterien man zugrunde legt.": "Al final depende de qué criterios se tomen como base.",
  "Ich räume ein dass da etwas dran ist, würde die Sache aber gern noch von einer anderen Seite betrachten.": "Admito que algo de razón hay, pero me gustaría mirar el asunto también desde otro ángulo.",
  "An Ihrer Stelle würde ich das nicht so kategorisch formulieren.": "Yo en su lugar no lo formularía de manera tan categórica.",
  "Ich versteh Ihren Einwand, gebe aber zu bedenken dass die Datenlage dünn ist.": "Entiendo su objeción, pero le hago notar que los datos son escasos.",
  "Vielleicht sehen wir das im Kern gar nicht so unterschiedlich, wie es zunächst scheint.": "Quizá en el fondo no lo veamos de forma tan distinta como parece al principio.",
  "An deiner Stelle würde ich das Angebot nicht ohne Bedenkzeit annehmen.": "Yo en tu lugar no aceptaría la oferta sin un tiempo para pensarlo.",
  "Wenn ich mehr Zeit hätte, würde ich mich gründlicher auf die Prüfung vorbereiten.": "Si tuviera más tiempo, me prepararía el examen más a fondo.",
  "Ich hätte das an ihrer Stelle ganz anders gemacht.": "Yo en su lugar lo habría hecho de una manera completamente distinta.",
  "Es wäre besser gewesen wenn wir das Problem gleich angesprochen hätten.": "Habría sido mejor que hubiéramos planteado el problema enseguida.",
  "Hättest du mich vorher gefragt, hätte ich dir davon abgeraten.": "Si me lo hubieras preguntado antes, te habría desaconsejado hacerlo.",
  "Im Nachhinein wäre es klüger gewesen, den Vertrag von einem Anwalt prüfen zu lassen.": "Visto en retrospectiva, habría sido más prudente hacer revisar el contrato por un abogado.",
  "Wenn ich das geahnt hätte, hätte ich mich niemals darauf eingelassen.": "Si lo hubiera sospechado, jamás me habría metido en eso.",
  "An seiner Stelle hätte ich mir die Entscheidung gründlicher überlegt, statt so voreilig zu handeln.": "Yo en su lugar me habría pensado mejor la decisión en vez de actuar con tanta precipitación.",
  "Es wird oft angenommen dass Homeoffice die Vereinbarkeit von Beruf und Familie automatisch verbessere.": "A menudo se supone que el teletrabajo mejora automáticamente la conciliación entre trabajo y familia.",
  "Man müsste die gesamte Arbeitskultur überdenken, um dem Problem wirklich gerecht zu werden.": "Habría que replantear toda la cultura laboral para hacer verdadera justicia al problema.",
  "Wären die politischen Rahmenbedingungen anders, ließe sich der ökologische Wandel deutlich beschleunigen.": "Si las condiciones políticas fueran otras, la transición ecológica podría acelerarse considerablemente.",
  "Die Auswirkungen des Klimawandels lassen sich längst nicht mehr leugnen.": "Los efectos del cambio climático hace tiempo que ya no se pueden negar.",
  "Es bleibt abzuwarten, inwiefern sich diese Entwicklung auf den Arbeitsmarkt auswirken wird.": "Está por ver hasta qué punto esta evolución afectará al mercado laboral.",
  "Man sollte nicht vergessen dass jede technische Neuerung auch mit gewissen Risiken verbunden ist.": "No hay que olvidar que toda innovación técnica conlleva también ciertos riesgos.",
  "Obwohl das Argument auf den ersten Blick überzeugt, halte ich es bei näherem Hinsehen für zu kurz gedacht.": "Aunque el argumento convence a primera vista, mirándolo de cerca me parece corto de miras.",
  "Ich bin keineswegs gegen den Vorschlag; im Gegenteil, ich halte ihn für längst überfällig.": "En absoluto estoy en contra de la propuesta; al contrario, me parece que llega con mucho retraso.",
  "Zwar hätte ich mir ein deutlicheres Ergebnis gewünscht, aber im Großen und Ganzen kann ich damit leben.": "Cierto que me habría gustado un resultado más claro, pero en líneas generales puedo vivir con él.",
  "Wenn wir die Fakten nüchtern abwägen, spricht letztlich mehr für den Umstieg als dagegen.": "Si sopesamos los hechos con serenidad, al final hay más a favor del cambio que en contra.",
  "Was den Zeitplan angeht, so seh ich noch erheblichen Klärungsbedarf bevor wir uns festlegen.": "En cuanto al calendario, sigo viendo bastante que aclarar antes de comprometernos.",
  "Beide Optionen haben ihre Vorzüge; entscheidend ist letztlich welches Risiko wir eher zu tragen bereit sind.": "Las dos opciones tienen sus ventajas; al final lo decisivo es qué riesgo estamos más dispuestos a asumir.",
  "Ich würde gern einen Termin vereinbaren, am besten noch in dieser Woche.": "Me gustaría pedir cita, a ser posible esta misma semana.",
  "Mir ist schwindelig.": "Estoy mareado.",
