  "Die Schmerzen strahlen vom Rücken bis ins linke Bein aus.": "El dolor irradia desde la espalda hasta la pierna izquierda.",
  "Nehmen Sie die Tabletten unbedingt bis zum Ende, auch wenn es Ihnen schon besser geht.": "Tómese las pastillas hasta el final sin falta, aunque ya se encuentre mejor.",
  "Ich bin gegen Penicillin allergisch, das steht auch in meinem Allergiepass.": "Soy alérgico a la penicilina; también consta en mi tarjeta de alergias.",
  "Falls sich Ihr Zustand verschlechtert, sollten Sie sofort in die Notaufnahme.": "Si su estado empeora, debería ir de inmediato a urgencias.",
