  "Halten Sie bitte die vorgeschriebene Dosierung genau ein.": "Respete exactamente la dosis prescrita, por favor.",
  "Beim Atmen tut mir die rechte Seite weh.": "Al respirar me duele el lado derecho.",
  "Das Rezept ist nur einen Monat lang gültig, lösen Sie es also rechtzeitig ein.": "La receta solo vale un mes, así que retírela a tiempo.",
