  "Der Arzt hat mir dringend geraten, mehr auf meine Ernährung zu achten.": "El médico me ha recomendado encarecidamente cuidar más la alimentación.",
  "Seit ich die neuen Tropfen nehme, sind die Beschwerden fast völlig abgeklungen.": "Desde que tomo las gotas nuevas, las molestias casi han desaparecido del todo.",
  "Ohne Überweisung nimmt der Facharzt Sie in der Regel gar nicht erst an.": "Sin volante, el especialista normalmente ni siquiera le atiende.",
