  "Ich hänge dir die Unterlagen gleich in einer Mail an.": "Te adjunto la documentación en un correo enseguida.",
  "Könntest du mir bis morgen eine kurze Rückmeldung geben?": "¿Me podrías dar una respuesta breve para mañana?",
  "Dafür bin ich leider nicht zuständig, aber ich leite es weiter.": "Por desgracia eso no es competencia mía, pero lo remito.",
  "Wir sollten das unbedingt vorher intern abstimmen.": "Eso deberíamos acordarlo internamente antes, sin falta.",
  "Das lässt sich so leider nicht umsetzen.": "Por desgracia eso no se puede hacer así.",
  "Ich fürchte wir werden die Frist nicht ganz halten können.": "Me temo que no vamos a poder cumplir del todo el plazo.",
  "Wie sind wir da eigentlich verblieben?": "¿En qué habíamos quedado exactamente?",
  "Ich würde das gerne noch einmal mit dir abstimmen bevor es rausgeht.": "Me gustaría contrastarlo contigo una vez más antes de que salga.",
  "Können wir den Termin eventuell verschieben?": "¿Podríamos aplazar la reunión?",
  "Ich bin da noch nicht ganz überzeugt.": "En eso todavía no estoy del todo convencido.",
  "Worum geht's genau?": "¿De qué se trata exactamente?",
