  "Melde dich einfach wenn irgendetwas unklar ist.": "Avísame sin más si algo no queda claro.",
  "Laut einer aktuellen Studie hat sich die soziale Ungleichheit in den letzten Jahren weiter verschärft.": "Según un estudio reciente, la desigualdad social se ha agravado todavía más en los últimos años.",
  "Es wird davon ausgegangen dass die Reform erhebliche Auswirkungen auf den Arbeitsmarkt haben wird.": "Se da por supuesto que la reforma tendrá efectos considerables sobre el mercado laboral.",
  "Der drastische Anstieg der Mietpreise trifft vor allem Familien mit geringem Einkommen.": "La subida drástica de los alquileres afecta sobre todo a las familias con pocos ingresos.",
  "Die Regierung sieht sich mit wachsender Kritik aus der Bevölkerung konfrontiert.": "El Gobierno se ve enfrentado a una crítica creciente por parte de la población.",
