  "Die Politik steht vor der Herausforderung, Wirtschaftswachstum und Klimaschutz miteinander zu vereinbaren.": "La política se enfrenta al reto de conciliar el crecimiento económico con la protección del clima.",
  "Immer mehr Menschen ziehen es vor, sich ihre Nachrichten online zusammenzustellen.": "Cada vez más gente prefiere componerse sus propias noticias por internet.",
  "In der öffentlichen Debatte wird häufig übersehen, wie komplex diese Zusammenhänge tatsächlich sind.": "En el debate público se suele pasar por alto lo complejas que son en realidad estas relaciones.",
