  "Es lässt sich nicht bestreiten dass die Digitalisierung unseren Alltag grundlegend verändert hat.": "No se puede negar que la digitalización ha cambiado nuestra vida diaria de raíz.",
  "Kurzfristige Lösungen greifen bei einem strukturellen Problem meist zu kurz.": "Las soluciones a corto plazo suelen quedarse cortas ante un problema estructural.",
