  "Da seh ich schwarz.": "Ahí lo veo muy negro.",
  "In meiner Hausarbeit setz ich mich kritisch mit der gängigen Forschungsmeinung auseinander.": "En mi trabajo me enfrento críticamente a la opinión dominante en la investigación.",
  "Die Fragestellung muss so präzise formuliert sein dass sie im vorgegebenen Umfang zu bearbeiten ist.": "La pregunta de investigación debe formularse con tal precisión que pueda tratarse en la extensión prevista.",
  "Ich vertrete die These dass sich der Wandel nicht allein ökonomisch erklären lässt.": "Defiendo la tesis de que el cambio no puede explicarse solo en términos económicos.",
  "Jede Behauptung sollte sich nachvollziehbar anhand der Quellen belegen lassen.": "Toda afirmación debería poder demostrarse de forma comprensible a partir de las fuentes.",
  "Bevor man eine eigene Position bezieht, sollte man den aktuellen Forschungsstand darlegen.": "Antes de tomar una posición propia hay que exponer el estado actual de la investigación.",
