  "Gegenargumente darf man nicht verschweigen, sondern muss sie ernst nehmen und entkräften.": "Los contraargumentos no se pueden silenciar: hay que tomarlos en serio y refutarlos.",
  "Leuchtet mir ein.": "Lo veo claro.",
  "In der mündlichen Prüfung kommt es weniger auf Details an als auf das Verständnis der Zusammenhänge.": "En el examen oral importan menos los detalles que entender las relaciones.",
  "Wenn du zitierst, musst du die Quelle korrekt angeben, sonst gilt das als Plagiat.": "Cuando citas tienes que indicar bien la fuente; si no, cuenta como plagio.",
  "Ich hab den Abgabetermin um zwei Wochen verschieben lassen weil ich krank war.": "He hecho aplazar la fecha de entrega dos semanas porque estaba enfermo.",
