  "Gehen Sie ruhig vor, ich hab Zeit.": "Pase usted, que yo no tengo prisa.",
  "Ich hab nur zwei Sachen — darf ich vielleicht kurz vor?": "Solo llevo dos cosas, ¿me deja pasar?",
  "Machen die nicht mal 'ne zweite Kasse auf?": "¿No pueden abrir otra caja?",
  "Entschuldigung, arbeiten Sie hier?": "Perdone, ¿trabaja usted aquí?",
  "Können Sie mal hinten nachschauen ob Sie die noch in 42 haben?": "¿Puede mirar en el almacén si les queda en la 42?",
  "Bei mir ist nie was angekommen.": "A mí no me llegó nunca nada.",
  "Im Karton war was ganz anderes drin.": "En la caja había algo completamente distinto.",
  "Wie lange dauert das mit der Erstattung?": "¿Cuánto tarda la devolución del dinero?",
  "Was ist Ihr letzter Preis?": "¿Cuál es su último precio?",
  "Wenn ich beide nehm, machen Sie mir dann einen Preis?": "Si me llevo los dos, ¿me hace precio?",
  "Da ist ein Kratzer — geht da noch was am Preis?": "Tiene un arañazo, ¿se puede rebajar algo el precio?",
  "Der lässt sich seit gestern nicht mehr einschalten.": "Desde ayer ya no se enciende.",
  "Ich würde das gern reklamieren.": "Querría poner una reclamación por defecto.",
  "Ist da noch Garantie drauf?": "¿Todavía tiene garantía?",
  "Und wer zahlt mir jetzt die Rücksendung?": "¿Y quién me paga ahora el envío de devolución?",
  "Kann ich bitte mit dem Filialleiter sprechen?": "¿Puedo hablar con el encargado, por favor?",
  "Geht da vielleicht was auf Kulanz?": "¿Cabría alguna solución comercial?",
  "Ich hab's geschenkt bekommen, deswegen hab ich keinen Bon.": "Me lo regalaron, por eso no tengo tique.",
  "Krieg ich dann nur einen Gutschein?": "¿Entonces solo me dan un vale?",
  "Kann ich das auch in einer anderen Filiale zurückgeben?": "¿Lo puedo devolver también en otra tienda?",
  "Ich glaub Sie haben sich vertan.": "Creo que se ha equivocado.",
  "Ich hatte Ihnen einen Fünfziger gegeben.": "Le había dado un billete de cincuenta.",
  "Da haben Sie mir zu wenig rausgegeben.": "Me ha devuelto de menos.",
  "Sind Sie der Letzte?": "¿Es usted el último?",
