  "Können Sie mir zeigen wo das steht?": "¿Me puede enseñar dónde está?",
  "Der Fahrer hat's einfach in den Hausflur gestellt.": "El repartidor lo dejó tal cual en el portal.",
  "Können Sie mir sagen, wann das ungefähr geliefert wird?": "¿Me puede decir más o menos cuándo lo entregan?",
  "Zehn Euro und ich nehm's sofort mit.": "Diez euros y me lo llevo ahora mismo.",
  "Ich hab leider nur zwanzig dabei.": "Por desgracia solo llevo veinte.",
  "Ich mach noch eine Runde und komm dann wieder.": "Doy otra vuelta y vuelvo.",
  "Ich glaub ich hab deinen Eimer kaputtgemacht — ich ersetz den natürlich.": "Creo que te he roto el cubo; te lo repongo, claro.",
  "Mir geht's heute nicht so gut.": "Hoy no me encuentro muy bien.",
  "Ich fühl mich total angeschlagen.": "Me siento hecho polvo.",
