  "Ich hab so Krämpfe, ich kann kaum stehen.": "Tengo unos calambres que casi no puedo estar de pie.",
  "Hast du zufällig 'n Tampon für mich?": "¿Tienes por casualidad un tampón?",
  "Ich leg mich mit 'ner Wärmflasche hin.": "Me voy a tumbar con una bolsa de agua caliente.",
  "Ich bin umgeknickt.": "Me he torcido el tobillo.",
  "Ich hab mich geschnitten, hast du ein Pflaster?": "Me he cortado, ¿tienes una tirita?",
  "Bist du wieder fit?": "¿Ya estás recuperado?",
  "Geht's wieder?": "¿Ya estás mejor?",
  "Soll ich dir was aus der Apotheke mitbringen?": "¿Te traigo algo de la farmacia?",
  "Kurier dich erst mal richtig aus.": "Cúrate bien del todo primero.",
  "Ruh dich mal richtig aus, der Rest kann warten.": "Descansa bien, que lo demás puede esperar.",
  "Werd erst mal wieder gesund, alles andere klärt sich.": "Ponte bueno primero, que lo demás ya se arreglará.",
  "Ich hab's im Rücken.": "Me ha dado la espalda.",
  "Mir kratzt der Hals, das wird bestimmt eine Erkältung.": "Me pica la garganta, seguro que es un resfriado.",
  "Trink mal was, du siehst richtig blass aus.": "Bebe algo, que estás muy pálido.",
  "Mein Kreislauf macht heute nicht mit.": "Hoy tengo la tensión por los suelos.",
  "Ich bin heute völlig gerädert.": "Hoy estoy completamente machacado.",
  "Mir ist schon den ganzen Morgen übel.": "Llevo con náuseas toda la mañana.",
  "Ich schlepp mich seit Tagen so durch.": "Llevo días arrastrándome así.",
  "Fass mal meine Stirn an, ich glaub ich glüh.": "Tócame la frente, creo que estoy ardiendo.",
  "Mir dröhnt der Schädel.": "Me retumba la cabeza.",
  "Nie wieder Alkohol. Bis Samstag.": "Nunca más alcohol. Hasta el sábado.",
  "Ich brauch jetzt was richtig Fettiges.": "Ahora mismo necesito algo bien grasiento.",
  "Ich hau mich kurz aufs Ohr.": "Me echo un rato.",
  "Ich lieg abends stundenlang wach und grüble.": "Por las noches me quedo horas despierta dándole vueltas.",
  "Du siehst fertig aus. Schlecht geschlafen?": "Tienes cara de agotado. ¿Has dormido mal?",
  "Ich hab gerade voll PMS, nimm's nicht persönlich.": "Ahora mismo tengo un síndrome premenstrual horrible, no te lo tomes a mal.",
  "Ich bin gerade total nah am Wasser gebaut.": "Ahora mismo lloro por cualquier cosa.",
  "Gesundheit!": "¡Jesús!",
  "Meine Augen jucken wie verrückt.": "Me pican los ojos muchísimo.",
  "Hast du mal ein Tempo?": "¿Tienes un pañuelo?",
  "Ich hab mir den kleinen Zeh gestoßen.": "Me he dado con el dedo pequeño del pie.",
  "Ich hab Hexenschuss, ich komm nicht mal aus dem Bett.": "Me ha dado un lumbago, ni salgo de la cama.",
  "Halb so wild, das sieht schlimmer aus, als es ist.": "No es para tanto, parece peor de lo que es.",
  "Ist das ansteckend, oder kann ich vorbeikommen?": "¿Es contagioso o puedo pasarme?",
  "Bleib bloß weg, ich will dich nicht anstecken.": "No te acerques, que no te quiero contagiar.",
  "Na, wie geht's dem Patienten?": "¿Qué, cómo está el paciente?",
  "Bleib liegen, ich mach das schon.": "No te levantes, que ya lo hago yo.",
  "Du gehst heute nirgendwo hin.": "Hoy no vas a ninguna parte.",
  "Mach mal langsam, du bist doch grad erst wieder auf den Beinen.": "Ve despacio, que acabas de recuperarte.",
  "Das klingt echt anstrengend.": "Eso suena agotador.",
