  "Irgendwas stimmt doch nicht, oder?": "Algo no va bien, ¿verdad?",
  "Du wirkst gerade irgendwie neben der Spur.": "Ahora mismo se te ve un poco ido.",
  "Und jetzt nochmal ehrlich: Wie geht's dir?": "Y ahora en serio: ¿cómo estás?",
  "Willst du reden oder lieber abgelenkt werden?": "¿Quieres hablar o prefieres distraerte?",
  "Soll ich einfach nur zuhören?": "¿Quieres que solo te escuche?",
  "Du musst nichts sagen, ich bleib einfach kurz hier.": "No tienes que decir nada, me quedo aquí un rato y ya.",
  "Mhm. Und dann?": "Ajá. ¿Y luego?",
  "Puh, das ist ja heftig.": "Uf, eso es muy fuerte.",
  "Ach du Scheiße, echt?": "Ay, joder, ¿en serio?",
  "Das kann man nicht schönreden, das ist einfach scheiße.": "Eso no se puede maquillar: es una mierda y ya.",
  "Das würde mich auch umhauen.": "A mí eso también me dejaría hecho polvo.",
  "Ich weiß auch nicht was man da sagen soll.": "Yo tampoco sé qué se dice en estos casos.",
  "Du musst dich vor mir nicht zusammenreißen.": "Conmigo no tienes que aguantar el tipo.",
  "Du hast schon ganz andere Sachen geschafft.": "Has salido de cosas mucho peores.",
  "Das kriegst du hin, echt.": "Esto lo sacas, de verdad.",
  "Wie geil ist das denn!": "¡Qué pasada!",
  "Das hast du dir sowas von verdient!": "¡Te lo mereces con creces!",
  "Ich hab Mist gebaut, und es tut mir wirklich leid.": "La he liado y lo siento de verdad.",
  "Ich will mich gar nicht rausreden.": "No pienso poner excusas.",
  "Das hätte ich dir nicht so an den Kopf werfen dürfen.": "No debería habértelo soltado así.",
  "Ich bin gerade selber ziemlich am Limit.": "Yo también estoy bastante al límite ahora mismo.",
  "Können wir morgen drüber reden? Heute schaff ich's nicht mehr.": "¿Lo hablamos mañana? Hoy ya no puedo más.",
  "Ich hör dir gern zu, aber Ratschläge hab ich keine.": "Te escucho encantado, pero consejos no tengo.",
  "Du meldest dich gar nicht mehr. Ist bei dir alles okay?": "Ya no das señales de vida. ¿Va todo bien?",
  "Du sagst zwar, alles gut, aber ich kauf dir das nicht ab.": "Dices que todo bien, pero no te lo compro.",
  "Seit wann geht das schon so?": "¿Desde cuándo lleva pasando esto?",
  "Was brauchst du gerade? Ganz ehrlich.": "¿Qué necesitas ahora mismo? Con toda sinceridad.",
